style.css:
@-moz-document url-prefix("http"), url-prefix("https") {
/* Apply Minecraft font to text elements */
    body, p, span, li, a, h1, h2, h3, h4, h5, h6, button, input, textarea {
        font-family: 'Minecraft', sans-serif !important;
    }

    /* Optional: Dark mode styling */
    body {
        background-color: #1e1e1e !important;
        color: #f0f0f0 !important;
    }

    /* Optional: Link styling */
    a {
        color: #00ff00 !important;
        text-decoration: none !important;
    }
    a:hover {
        text-decoration: underline !important;
    }

    /* Optional: Headings styling */
    h1, h2, h3, h4, h5, h6 {
        font-family: 'Minecraft', sans-serif !important;
    }

    /* Optional: Buttons & Inputs styling */
    button, input, textarea {
        font-family: 'Minecraft', sans-serif !important;
        color: #f0f0f0 !important;
        background-color: #2e2e2e !important;
        border: 1px solid #00ff00 !important;
    }

    /* Optional: Lists styling */
    ul, ol, li {
        font-family: 'Minecraft', sans-serif !important;
    }
}

@-moz-document url-prefix("http"), url-prefix("https") {
/* Apply font only to main text elements */
    body, p, span, li, a, h1, h2, h3, h4, h5, h6 {
        font-family: 'Minecraft', sans-serif !important;
        font-size: 16px !important; /* minimum readable size */
        line-height: 1.5 !important;
    }

    /* Optional dark mode */
    body {
        background-color: #1e1e1e !important;
        color: #f0f0f0 !important;
    }

    /* Links */
    a {
        color: #00ff00 !important;
        text-decoration: none !important;
    }
    a:hover {
        text-decoration: underline !important;
    }
}
